import type { Filter, FilterOperator, QueryTable, Sort, Dictionary } from './types'
import { IQueryModifier, QueryModifier } from './QueryModifier'

export interface IQueryFilter {
  filter: (column: string, operator: FilterOperator, value: string) => IQueryFilter
  match: (criteria: Dictionary<any>) => IQueryFilter
  order: (table: string, column: string, ascending?: boolean, nullsFirst?: boolean) => IQueryFilter
}

export class QueryFilter implements IQueryFilter, IQueryModifier {
  protected filters: Filter[] = []
  protected sorts: Sort[] = []

  constructor(
    protected table: QueryTable,
    protected action: 'count' | 'delete' | 'insert' | 'select' | 'update' | 'truncate',
    protected actionValue?: string | string[] | Dictionary<any> | Dictionary<any>[],
    protected actionOptions?: { returning: boolean; enumArrayColumns?: string[] }
  ) {}

  filter(column: string, operator: FilterOperator, value: any) {
    this.filters.push({ column, operator, value })
    return this
  }

  match(criteria: Dictionary<any>) {
    Object.entries(criteria).map(([column, value]) => {
      this.filters.push({ column, operator: '=', value })
    })
    return this
  }

  order(table: string, column: string, ascending = true, nullsFirst = false) {
    this.sorts.push({
      table: table,
      column: column,
      ascending,
      nullsFirst,
    })
    return this
  }

  range(from: number, to: number) {
    return this._getQueryModifier().range(from, to)
  }

  toSql() {
    return this._getQueryModifier().toSql()
  }

  _getQueryModifier() {
    return new QueryModifier(this.table, this.action, {
      actionValue: this.actionValue,
      actionOptions: this.actionOptions,
      filters: this.filters,
      sorts: this.sorts,
    })
  }
}
import type { Filter, QueryPagination, QueryTable, Sort, Dictionary } from './types'
import {
  countQuery,
  deleteQuery,
  insertQuery,
  selectQuery,
  truncateQuery,
  updateQuery,
} from './Query.utils'

export interface IQueryModifier {
  range: (from: number, to: number) => QueryModifier
  toSql: () => string
}

export class QueryModifier implements IQueryModifier {
  protected pagination?: QueryPagination

  constructor(
    protected table: QueryTable,
    protected action: 'count' | 'delete' | 'insert' | 'select' | 'update' | 'truncate',
    protected options?: {
      actionValue?: string | string[] | Dictionary<any> | Dictionary<any>[]
      actionOptions?: { returning?: boolean; cascade?: boolean; enumArrayColumns?: string[] }
      filters?: Filter[]
      sorts?: Sort[]
    }
  ) {}

  /**
   * Limits the result to rows within the specified range, inclusive.
   *
   * @param from  The starting index from which to limit the result, inclusive.
   * @param to  The last index to which to limit the result, inclusive.
   */
  range(from: number, to: number) {
    this.pagination = { offset: from, limit: to - from + 1 }
    return this
  }

  /**
   * Return SQL string for query chains
   */
  toSql() {
    try {
      const { actionValue, actionOptions, filters, sorts } = this.options ?? {}
      switch (this.action) {
        case 'count': {
          return countQuery(this.table, { filters })
        }
        case 'delete': {
          return deleteQuery(this.table, filters, {
            returning: actionOptions?.returning,
            enumArrayColumns: actionOptions?.enumArrayColumns,
          })
        }
        case 'insert': {
          return insertQuery(this.table, actionValue as Dictionary<any>[], {
            returning: actionOptions?.returning,
            enumArrayColumns: actionOptions?.enumArrayColumns,
          })
        }
        case 'select': {
          return selectQuery(this.table, actionValue as string | undefined, {
            filters,
            pagination: this.pagination,
            sorts,
          })
        }
        case 'update': {
          return updateQuery(this.table, actionValue as Dictionary<any>, {
            filters,
            returning: actionOptions?.returning,
            enumArrayColumns: actionOptions?.enumArrayColumns,
          })
        }
        case 'truncate': {
          return truncateQuery(this.table, {
            cascade: actionOptions?.cascade,
          })
        }
        default: {
          return ''
        }
      }
    } catch (error) {
      throw error
    }
  }
}

